# Generated by manage.py generate_test_cases.
from django.urls import reverse

from bloomerp.models.users.user import User
from bloomerp.tests.base import (
    BloomerpDetailViewTestCase,
    ExpectedResult,
    RequestScenario,
    ModelRequestScenario,
)
from bloomerp.utils.models import get_detail_view_url


class TestUserAdminPasswordResetView(BloomerpDetailViewTestCase):
    """Tests class `UserAdminPasswordResetView` from `bloomerp/views/users/admin_reset_password.py`."""

    view_name = 'admin_reset_password_for_user'
    model = User

    def create_test_object(self):
        return self.normal_user

    def get_test_scenarios(self) -> list[RequestScenario]:
        return [
            RequestScenario(
                name="Administrator opens target user's password reset form",
                description=(
                    "UC: An administrator opens another user's reset page.\n"
                    "Expected Result: The password confirmation form is rendered."
                ),
                user=self.admin_user,
                expected=ExpectedResult(response_validators=self.contains_text('name="password1"')),
            ),
            RequestScenario(
                name="Administrator resets another user's password",
                description=(
                    "UC: An administrator supplies matching passwords for a user.\n"
                    "Expected Result: The password changes and the response redirects to that user's detail view."
                ),
                method="POST",
                user=self.admin_user,
                data={
                    "password1": "admin-set-password-789",
                    "password2": "admin-set-password-789",
                },
                expected=ExpectedResult(
                    status_code=302,
                    response_validators=self.admin_password_was_reset,
                ),
            ),
            RequestScenario(
                name="Non-superuser cannot use administrator reset view",
                description=(
                    "UC: A regular user opens the administrator reset route.\n"
                    "Expected Result: The view returns 403."
                ),
                user=self.normal_user,
                prepare=self.refresh_normal_user,
                expected=ExpectedResult(status_code=403),
            ),
        ]

    def refresh_normal_user(self, _scenario):
        self.normal_user.refresh_from_db()

    def admin_password_was_reset(self, response):
        self.normal_user.refresh_from_db()
        return (
            self.normal_user.check_password("admin-set-password-789")
            and response.headers.get("Location")
            == reverse(get_detail_view_url(User), kwargs={"pk": self.normal_user.pk})
        )
